"use strict";(self.webpackChunkazurelocal_github_io=self.webpackChunkazurelocal_github_io||[]).push([[25547],{92911:e=>{e.exports=JSON.parse('{"tag":{"label":"os-configuration","permalink":"/docs/tags/os-configuration","allTagsPath":"/docs/tags","count":21,"items":[{"id":"implementation/04-cluster-deployment/phase-03-os-configuration/automated-os-configuration","title":"Automated OS Configuration (One Run)","description":"Configure every node\'s OS in one run with the azurelocal-toolkit: standalone or from a GitHub or GitLab pipeline, with method detection, plan, approval, apply and verify, the master-file keys it reads, clear_storage, exit codes and troubleshooting.","permalink":"/docs/implementation/04-cluster-deployment/phase-03-os-configuration/automated-os-configuration"},{"id":"implementation/04-cluster-deployment/choose-your-route","title":"Choose Your Route: ISO or Simplified Provisioning","description":"Two routes lead to the same Azure Local cluster deployment. A flow chart and a decision matrix show which OS installation, OS configuration and Arc registration steps each route needs before Validate.","permalink":"/docs/implementation/04-cluster-deployment/choose-your-route"},{"id":"implementation/04-cluster-deployment/phase-03-os-configuration/how-the-run-works","title":"How the OS Configuration Run Works","description":"Every step of the automated OS configuration run in the order it executes: what is read first, what counts as a change, the idempotent re-run, the restart points, the three management address modes, the SAN-only steps, the SBE route, the retry on state Unknown, per-node continue on failure and the plan, approval, apply and verify stages.","permalink":"/docs/implementation/04-cluster-deployment/phase-03-os-configuration/how-the-run-works"},{"id":"implementation/04-cluster-deployment/phase-03-os-configuration/task-01-enable-winrm-for-remote-management","title":"Task 01: Enable WinRM for Remote Management","description":"Enable Windows Remote Management on all Azure Local nodes via iDRAC Virtual Console. Must run locally on each node \u2014 WinRM cannot be enabled remotely before it exists.","permalink":"/docs/implementation/04-cluster-deployment/phase-03-os-configuration/task-01-enable-winrm-for-remote-management"},{"id":"implementation/04-cluster-deployment/phase-03-os-configuration/task-02-enable-rdp","title":"Task 02: Enable RDP","description":"Enable Remote Desktop Protocol on all Azure Local nodes for graphical remote access during configuration and troubleshooting.","permalink":"/docs/implementation/04-cluster-deployment/phase-03-os-configuration/task-02-enable-rdp"},{"id":"implementation/04-cluster-deployment/phase-03-os-configuration/task-03-configure-static-ip-address","title":"Task 03: Configure Static IP Address","description":"Configure static IP addresses on the management network adapter for each Azure Local cluster node using explicit values from infrastructure.yml.","permalink":"/docs/implementation/04-cluster-deployment/phase-03-os-configuration/task-03-configure-static-ip-address"},{"id":"implementation/04-cluster-deployment/phase-03-os-configuration/task-04-disable-dhcp-on-management-adapter","title":"Task 04: Disable DHCP on All Adapters","description":"Disable DHCP on all network adapters except virtual and management adapters to lock in static IP configuration across all Azure Local cluster nodes.","permalink":"/docs/implementation/04-cluster-deployment/phase-03-os-configuration/task-04-disable-dhcp-on-management-adapter"},{"id":"implementation/04-cluster-deployment/phase-03-os-configuration/task-05-configure-dns-servers","title":"Task 05: Configure DNS Servers","description":"Configure primary and secondary DNS server addresses on the management NIC of each Azure Local cluster node using explicit values from infrastructure.yml.","permalink":"/docs/implementation/04-cluster-deployment/phase-03-os-configuration/task-05-configure-dns-servers"},{"id":"implementation/04-cluster-deployment/phase-02-os-installation/simplified-provisioning/task-06-prepare-for-validate","title":"Task 06: Prepare Machines for Validate","description":"After simplified machine provisioning, install the OEM drivers and SBE, set one static management address with one default gateway, DNS and time, and check every machine before cluster Validate.","permalink":"/docs/implementation/04-cluster-deployment/phase-02-os-installation/simplified-provisioning/task-06-prepare-for-validate"},{"id":"implementation/04-cluster-deployment/phase-03-os-configuration/task-06-verify-dns-client-configuration","title":"Task 06: Verify DNS Client Configuration","description":"Verify that DNS servers are correctly configured on the management NIC of each Azure Local node and that critical Azure endpoints resolve successfully.","permalink":"/docs/implementation/04-cluster-deployment/phase-03-os-configuration/task-06-verify-dns-client-configuration"},{"id":"implementation/04-cluster-deployment/phase-03-os-configuration/task-07-configure-time-synchronization-ntp","title":"Task 07: Configure Time Synchronization (NTP)","description":"Configure the NTP time source on each Azure Local node using w32tm \u2014 required for Kerberos authentication and AD domain operations.","permalink":"/docs/implementation/04-cluster-deployment/phase-03-os-configuration/task-07-configure-time-synchronization-ntp"},{"id":"implementation/04-cluster-deployment/phase-03-os-configuration/task-08-enable-icmp-ping","title":"Task 08: Enable ICMP (Ping)","description":"Enable ICMPv4 and ICMPv6 inbound firewall rules on each Azure Local node to allow ping for network diagnostics and connectivity validation.","permalink":"/docs/implementation/04-cluster-deployment/phase-03-os-configuration/task-08-enable-icmp-ping"},{"id":"implementation/04-cluster-deployment/phase-03-os-configuration/task-09-disable-unused-network-adapters","title":"Task 09: Disable Unused Network Adapters","description":"Disable network adapters not used for management to prevent configuration issues during cluster deployment","permalink":"/docs/implementation/04-cluster-deployment/phase-03-os-configuration/task-09-disable-unused-network-adapters"},{"id":"implementation/04-cluster-deployment/phase-03-os-configuration/task-10-configure-hostname","title":"Task 10: Configure Hostname","description":"Set the computer hostname for each node according to naming standards","permalink":"/docs/implementation/04-cluster-deployment/phase-03-os-configuration/task-10-configure-hostname"},{"id":"implementation/04-cluster-deployment/phase-03-os-configuration/task-11-clear-previous-storage-configuration-conditional","title":"Task 11: Clear Previous Storage Configuration (Conditional)","description":"Clear previous Storage Spaces Direct configuration if redeploying on existing hardware","permalink":"/docs/implementation/04-cluster-deployment/phase-03-os-configuration/task-11-clear-previous-storage-configuration-conditional"},{"id":"implementation/04-cluster-deployment/phase-03-os-configuration/task-12-install-fc-hba-drivers-conditional","title":"Task 12: Install FC HBA Drivers (Conditional)","description":"Install Fibre Channel HBA drivers (or the dedicated iSCSI adapter drivers) on Azure Local nodes for SAN disaggregated deployments, and get the zoning timing right for disaggregated versus hybrid","permalink":"/docs/implementation/04-cluster-deployment/phase-03-os-configuration/task-12-install-fc-hba-drivers-conditional"},{"id":"implementation/04-cluster-deployment/phase-03-os-configuration/task-13-configure-mpio-and-vendor-msdsm-conditional","title":"Task 13: Configure MPIO and Vendor MSDSM (Conditional)","description":"Verify Windows Multipath I/O, register the SAN vendor with MSDSM and claim the array\'s disks, for Fibre Channel and iSCSI SAN disaggregated deployments on Azure Local 2610","permalink":"/docs/implementation/04-cluster-deployment/phase-03-os-configuration/task-13-configure-mpio-and-vendor-msdsm-conditional"},{"id":"implementation/04-cluster-deployment/phase-03-os-configuration/task-14-verify-san-lun-presentation-conditional","title":"Task 14: Verify SAN LUN Presentation (Conditional)","description":"Verify SAN LUN presentation (Fibre Channel or iSCSI) and confirm the infrastructure and performance history LUNs are RAW before Azure Local disaggregated deployment","permalink":"/docs/implementation/04-cluster-deployment/phase-03-os-configuration/task-14-verify-san-lun-presentation-conditional"},{"id":"implementation/04-cluster-deployment/phase-03-os-configuration/task-15-complete-combined-script-all-steps","title":"Task 15: Complete Combined Script (All Steps)","description":"Optional combined script that runs Tasks 02\u201310 in a single execution for faster deployment","permalink":"/docs/implementation/04-cluster-deployment/phase-03-os-configuration/task-15-complete-combined-script-all-steps"},{"id":"implementation/04-cluster-deployment/phase-03-os-configuration/task-16-phase03-verification","title":"Task 16: Phase 03 Verification","description":"Read-only verification of all Phase 03 OS Configuration tasks (01\u201315) across all cluster nodes","permalink":"/docs/implementation/04-cluster-deployment/phase-03-os-configuration/task-16-phase03-verification"},{"id":"implementation/04-cluster-deployment/phase-03-os-configuration/which-method-then-os-configuration","title":"Which Provisioning Method, Then OS Configuration","description":"A decision flow from the way the OS was installed (azurelocal-ztp simplified provisioning, or a manual ISO install) to OS configuration, method detection, the two paths, the converge check, ARM Validate and ARM Deploy, and how to tell which method you used.","permalink":"/docs/implementation/04-cluster-deployment/phase-03-os-configuration/which-method-then-os-configuration"}],"unlisted":false}}')}}]);